<?php
session_start();
require 'baseDeDatos.php';
requireAuthentication();
$tabla = $conn->query("SELECT c.nombre, COALESCE(SUM(CASE WHEN p.goles_local > p.goles_visitante AND p.id_club_local=c.id_club THEN 3 WHEN p.goles_local = p.goles_visitante AND (p.id_club_local=c.id_club OR p.id_club_visitante=c.id_club) THEN 1 WHEN p.goles_visitante > p.goles_local AND p.id_club_visitante=c.id_club THEN 3 ELSE 0 END),0) AS puntos, COUNT(p.id_partido) AS partidos, COALESCE(SUM(CASE WHEN p.id_club_local=c.id_club THEN p.goles_local WHEN p.id_club_visitante=c.id_club THEN p.goles_visitante ELSE 0 END),0) AS gf, COALESCE(SUM(CASE WHEN p.id_club_local=c.id_club THEN p.goles_visitante WHEN p.id_club_visitante=c.id_club THEN p.goles_local ELSE 0 END),0) AS gc FROM club c LEFT JOIN partidos p ON p.id_club_local=c.id_club OR p.id_club_visitante=c.id_club GROUP BY c.id_club,c.nombre ORDER BY puntos DESC, (gf-gc) DESC, gf DESC");
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Clasificación</title><link href="CSSmenuInicio.css" rel="stylesheet"><style>main{padding:20px}table{border-collapse:collapse;width:100%;background:#fff}th,td{padding:9px;border:1px solid #ddd}th{background:#2c3e50;color:#fff}</style></head><body><header><div class="MGfut"><h2>MG Fut</h2></div></header><main><p><a href="menuInicio.php">Volver al menú</a></p><h2>Tabla de clasificación</h2><table><tr><th>#</th><th>Club</th><th>Partidos</th><th>GF</th><th>GC</th><th>Puntos</th></tr><?php $pos=1; while($c=$tabla->fetch_assoc()): ?><tr><td><?php echo $pos++; ?></td><td><?php echo htmlspecialchars($c['nombre']); ?></td><td><?php echo $c['partidos']; ?></td><td><?php echo $c['gf']; ?></td><td><?php echo $c['gc']; ?></td><td><strong><?php echo $c['puntos']; ?></strong></td></tr><?php endwhile; ?></table></main></body></html>
